def _ingress_sni_hosts(item, index):
    spec = get(item, "spec", dict)
    rules = list_of_objects(get(spec, "rules", list))
    tls = list_of_objects(get(spec, "tls", list))
    covered = set()
    for entry in tls:
        secret = optional(entry, "secretName", "", str)
        hosts = optional(entry, "hosts", [], list)
        if any(not isinstance(host, str) for host in hosts):
            return unknown("malformed Ingress TLS hosts")
        if secret.strip():
            covered.update(hosts)
    hosts = [get(rule, "host", str) for rule in rules if "host" in rule]
    missing = sorted({host for host in hosts if host and host not in covered})
    return result(bool(missing), rule_hosts=hosts, hosts_without_tls_secret=missing,
                  semantics="Ingress TLS declaration; certificate validity and controller behavior not tested")

def _ingress_tls_secret(item, index):
    namespace = get(item, "metadata.namespace", str)
    rules = list_of_objects(get(item, "spec.rules", list))
    tls = list_of_objects(get(item, "spec.tls", list))
    if not namespace:
        return unknown("Ingress namespace absent")
    def secret_names():
        names = {}
        for secret in complete_items(index, "secret_metadata"):
            name = get(secret, "metadata.name", str)
            secret_namespace = get(secret, "metadata.namespace", str)
            kind = get(secret, "type", str)
            key = (secret_namespace, name)
            if key in names:
                raise Unavailable("duplicate Secret metadata identity")
            names[key] = kind
        return names
    names = memoized(index, ("compliance_new_k8s_tls_secret_names",), secret_names)
    if not tls:
        return result(True, reason="Ingress has no TLS declaration")
    covered = set()
    missing = []
    for row in tls:
        secret_name = get(row, "secretName", str)
        hosts = get(row, "hosts", list)
        if any(not isinstance(host, str) or not host.strip() for host in hosts):
            return unknown("malformed Ingress TLS host")
        if not secret_name.strip():
            missing.append({"namespace": namespace, "secret": secret_name, "reason": "TLS Secret name is explicitly empty"})
            continue
        kind = names.get((namespace, secret_name))
        if kind is None:
            missing.append({"namespace": namespace, "secret": secret_name, "reason": "not found in complete scoped Secret metadata"})
        elif kind != "kubernetes.io/tls":
            missing.append({"namespace": namespace, "secret": secret_name, "reason": "not a kubernetes.io/tls Secret"})
        else:
            covered.update(hosts)
    rule_hosts = [get(row, "host", str) for row in rules if "host" in row]
    if any(not host.strip() for host in rule_hosts):
        return unknown("malformed Ingress rule host")
    uncovered = sorted(set(rule_hosts) - covered)
    return result(bool(missing or uncovered), namespace=namespace, missing_tls_secrets=missing,
                  rule_hosts_without_resolved_tls=uncovered,
                  semantics="Same-namespace Secret metadata and Ingress declaration; certificate and controller runtime are not assessed")

@register(BACKEND_ID, "k8s", "network", "ingress",
          "nginx TLS Ingress declares HTTPS or GRPCS for resolved backend Services",
          "medium", "SC-8",
          "Review backend TLS support with the Service owner and plan migration from retired ingress-nginx to a supported controller; during a reviewed transition, declare HTTPS or GRPCS only after backend TLS is configured and verify the result.",
          dependencies=["ingress", "ingressclass", "service"])
def ingress_backend_protocol(item, index):
    parsed = _nginx_tls(item, index)
    if len(parsed) == 2:
        return parsed
    spec, metadata, annotations = parsed
    namespace = get(metadata, "namespace", str)
    if not namespace:
        return unknown("Ingress namespace is absent")
    services = {}
    for service in complete_items(index, "service"):
        key = (get(service, "metadata.namespace", str), get(service, "metadata.name", str))
        if key in services:
            return unknown("duplicate Service identity in complete inventory", namespace=key[0], name=key[1])
        services[key] = service
    native = item.get("provenance", {}).get("evidence") == "read-only list"
    rules = list_of_objects(optional(spec, "rules", [], list) if native else get(spec, "rules", list))
    targets = []
    if "defaultBackend" in spec:
        backend = get(spec, "defaultBackend", dict)
        if "resource" in backend:
            return unknown("Ingress default resource backend is outside reviewed Service configuration")
        targets.append(get(backend, "service.name", str))
    for rule in rules:
        paths = list_of_objects(get(rule, "http.paths", list))
        for path in paths:
            targets.append(get(path, "backend.service.name", str))
    if not targets:
        return unknown("no rule backend Service was observed")
    unresolved = sorted({name for name in targets if not name or (namespace, name) not in services})
    if unresolved:
        return unknown("Ingress backend Service unresolved in complete same-namespace inventory",
                       unresolved_services=unresolved, namespace=namespace)
    protocol = annotations.get("nginx.ingress.kubernetes.io/backend-protocol")
    if protocol is not None and protocol not in ("HTTPS", "GRPCS", "HTTP", "GRPC", "FCGI", "AUTO_HTTP"):
        return unknown("unrecognized nginx backend protocol annotation", observed_protocol=protocol)
    return result(protocol not in ("HTTPS", "GRPCS"), declared_backend_protocol=protocol,
                  resolved_backend_services=sorted(set(targets)), namespace=namespace,
                  semantics="Ingress annotation and Service identity only; controller adoption and backend TLS runtime unverified")

